{"function": "() => {
  const result = {
    title: document.title.replace(' - YouTube', ''),
    videoTitle: '',
    channelName: '',
    subscriberCount: '',
    views: '',
    uploadDate: '',
    likes: '',
    description: '',
    comments: []
  };

  // Extract video title
  const titleElement = document.querySelector('h1.ytd-video-primary-info-renderer');
  if (titleElement) {
    result.videoTitle = titleElement.textContent.trim();
  } else {
    const h1Elements = document.querySelectorAll('h1');
    if (h1Elements.length > 0) {
      result.videoTitle = h1Elements[0].textContent.trim();
    }
  }

  // Extract channel info
  const channelElement = document.querySelector('#owner #channel-name a');
  if (channelElement) {
    result.channelName = channelElement.textContent.trim();
  }

  const subscriberElement = document.querySelector('#owner-sub-count');
  if (subscriberElement) {
    result.subscriberCount = subscriberElement.textContent.trim();
  }

  // Extract view count and upload date
  const viewCountElement = document.querySelector('#info .view-count');
  if (viewCountElement) {
    result.views = viewCountElement.textContent.trim();
  }

  const dateElement = document.querySelector('#info .date');
  if (dateElement) {
    result.uploadDate = dateElement.textContent.trim();
  }

  // Extract likes
  const likeButton = document.querySelector('ytd-toggle-button-renderer[aria-label*="like"]');
  if (likeButton) {
    const likeCount = likeButton.querySelector('.ytd-toggle-button-renderer');
    if (likeCount) {
      result.likes = likeCount.textContent.trim();
    }
  }

  // Extract description
  const descriptionElement = document.querySelector('#description-inline-expander yt-attributed-string');
  if (descriptionElement) {
    result.description = descriptionElement.textContent.trim();
  } else {
    const descElement = document.querySelector('#description');
    if (descElement) {
      result.description = descElement.textContent.trim();
    }
  }

  // Extract comments
  const commentElements = document.querySelectorAll('ytd-comment-thread-renderer');
  commentElements.forEach((comment, index) => {
    if (index < 50) { // Limit to 50 comments
      const commentObj = {
        author: '',
        time: '',
        text: '',
        likes: '',
        replies: ''
      };

      const authorElement = comment.querySelector('#author-text');
      if (authorElement) {
        commentObj.author = authorElement.textContent.trim();
      }

      const timeElement = comment.querySelector('#published-time-text a');
      if (timeElement) {
        commentObj.time = timeElement.textContent.trim();
      }

      const textElement = comment.querySelector('#content-text');
      if (textElement) {
        commentObj.text = textElement.textContent.trim();
      }

      const likeElement = comment.querySelector('#vote-count-middle');
      if (likeElement) {
        commentObj.likes = likeElement.textContent.trim();
      }

      const replyElement = comment.querySelector('#reply-count');
      if (replyElement) {
        commentObj.replies = replyElement.textContent.trim();
      }

      result.comments.push(commentObj);
    }
  });

  return result;
}"}

